import Foundation

/// Decides whether a pasteboard change should be recorded, and which of its
/// types are worth storing.
public struct CaptureRules: Sendable {
    /// Markers defined at nspasteboard.org that apps set on secrets and
    /// throwaway data. Password managers use these, so respecting them is the
    /// main way we avoid storing passwords.
    public static let defaultIgnoredTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    /// Password managers that may not set the markers above.
    public static let defaultIgnoredApps: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.bitwarden.desktop",
    ]

    /// Types that are never stored. File promises resolve lazily, so reading
    /// their data would make the source app write files to disk.
    public static let unstorableTypes: Set<String> = [
        "com.apple.pasteboard.promised-file-url",
        "com.apple.pasteboard.promised-file-content-type",
        "com.apple.NSFilePromiseItemMetaData",
        "com.apple.pasteboard.promised-suggested-file-name",
    ]

    public var ignoredTypes: Set<String>
    public var ignoredApps: Set<String>
    /// Copies larger than this are skipped to keep the store small.
    public var maxPayloadBytes: Int
    /// Marker the app puts on its own writes so they aren't captured twice.
    public var ownMarkerType: String?

    public init(
        ignoredTypes: Set<String> = CaptureRules.defaultIgnoredTypes,
        ignoredApps: Set<String> = CaptureRules.defaultIgnoredApps,
        maxPayloadBytes: Int = 20 * 1024 * 1024,
        ownMarkerType: String? = nil
    ) {
        self.ignoredTypes = ignoredTypes
        self.ignoredApps = ignoredApps
        self.maxPayloadBytes = maxPayloadBytes
        self.ownMarkerType = ownMarkerType
    }

    /// Checked before any data is read, using only the type list and the
    /// frontmost app.
    public func shouldInspect(types: [String], sourceBundleID: String?) -> Bool {
        if types.isEmpty { return false }
        if let source = sourceBundleID, ignoredApps.contains(source) { return false }
        if let marker = ownMarkerType, types.contains(marker) { return false }
        return !types.contains { ignoredTypes.contains($0) }
    }

    public func storableTypes(_ types: [String]) -> [String] {
        types.filter { !Self.unstorableTypes.contains($0) && $0 != ownMarkerType }
    }

    /// Checked after the data has been read.
    public func shouldStore(_ entries: [PasteboardEntry]) -> Bool {
        !entries.isEmpty && entries.totalBytes <= maxPayloadBytes
    }
}
